/* Monster easter egg — Alt+A. Sprite sheet assets/monster.png: 23 frames of
   276x300px, one gait cycle, 24fps source. Faces left by default, so it's
   mirrored below to walk left-to-right. */
:root {
  --monster-frame-w: 184px;
  --monster-frame-h: 200px;
  --monster-sheet-w: calc(var(--monster-frame-w) * 23);
  --monster-cycle: 0.96s;
  --monster-stride: 130px;
  --monster-crossing: 16s;
}

.monster-walker {
  display: none;
  position: fixed;
  left: 0;
  bottom: 12px;
  width: var(--monster-frame-w);
  height: var(--monster-frame-h);
  pointer-events: none;
  z-index: 999;
}

.monster-walker.is-walking {
  display: block;
  animation: monster-move-across var(--monster-crossing) linear 1 forwards;
}

.monster-character {
  position: absolute;
  inset: 0;
  transform: scaleX(-1);
}

.monster-shadow {
  position: absolute;
  right: 8%;
  bottom: 0;
  width: 42%;
  height: 11px;
  background: rgba(60, 80, 60, 0.22);
  border-radius: 50%;
  filter: blur(3px);
}

.monster-sprite {
  position: absolute;
  inset: 0;
  background-image: url("assets/monster.png");
  background-repeat: no-repeat;
  background-size: var(--monster-sheet-w) var(--monster-frame-h);
}

.monster-walker.is-walking .monster-sprite {
  animation: monster-walk-cycle var(--monster-cycle) steps(23) infinite;
}

@keyframes monster-walk-cycle {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--monster-sheet-w)) 0; }
}

@keyframes monster-move-across {
  from { transform: translateX(calc(-1 * var(--monster-frame-w))); }
  to   { transform: translateX(100vw); }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walker.is-walking {
    animation: none;
    transform: translateX(45vw);
  }
  .monster-walker.is-walking .monster-sprite {
    animation: none;
  }
}

