const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const target = 'file:///' + path.resolve('<run>/index.html').replace(/\\/g, '/');
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });

  await page.goto(target);

  const beforeClass = await page.getAttribute('.monster-walker', 'class');
  const beforeDisplay = await page.evaluate(() => getComputedStyle(document.querySelector('.monster-walker')).display);

  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');

  await page.waitForTimeout(300);
  const duringClass = await page.getAttribute('.monster-walker', 'class');
  const duringDisplay = await page.evaluate(() => getComputedStyle(document.querySelector('.monster-walker')).display);
  const crossing = await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--monster-crossing'));

  // press again while walking -> should be ignored (class stays, no restart)
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await page.waitForTimeout(200);
  const stillDuringClass = await page.getAttribute('.monster-walker', 'class');

  // wait long enough for a short crossing to finish, using reduced motion to keep test fast
  await browser.close();

  console.log(JSON.stringify({ beforeClass, beforeDisplay, duringClass, duringDisplay, crossing, stillDuringClass, errors }, null, 2));
})();
