  await page.goto(target);

  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await page.waitForTimeout(200);
  const duringClass = await page.getAttribute('.monster-walker', 'class');
  const duringDisplay = await page.evaluate(() => getComputedStyle(document.querySelector('.monster-walker')).display);
  const duringTransform = await page.evaluate(() => getComputedStyle(document.querySelector('.monster-walker')).transform);

  // second press while still showing -> ignored
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  const stillDuringClass = await page.getAttribute('.monster-walker', 'class');

  await page.waitForTimeout(2200); // past the 2000ms reduced-motion timeout
  const afterClass = await page.getAttribute('.monster-walker', 'class');
  const afterDisplay = await page.evaluate(() => getComputedStyle(document.querySelector('.monster-walker')).display);

  // retrigger should now work again
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await page.waitForTimeout(200);
  const retriggerClass = await page.getAttribute('.monster-walker', 'class');

  await browser.close();
  console.log(JSON.stringify({ duringClass, duringDisplay, duringTransform, stillDuringClass, afterClass, afterDisplay, retriggerClass, errors }, null, 2));
})();
